User: {'Id': 10237, 'Reputation': 128, 'CreationDate': '2012-03-30 10:39:30.0', 'DisplayName': 'daemonfire300', 'LastAccessDate': '2013-03-21 14:15:40.0', 'WebsiteUrl': 'http://bio.accountr.eu/work_in_progress', 'Location': 'Baden-Wurttemberg, Germany', 'AboutMe': '<p>I am a young programmer, which trys to get a scholar-ship for studying game design at the Quantm SAE Institute.\nFormerly studying   business information technology in munich.\nCurrently studying information technology at heidelberg university.</p>\n', 'Views': 8, 'UpVotes': 3, 'DownVotes': 0, 'AccountId': 63980, 'Age': 21, 'ProfileImageUrl': None}
