User: {'Id': 37053, 'Reputation': 111, 'CreationDate': '2014-01-08 21:40:31.0', 'DisplayName': 'venergiac', 'LastAccessDate': '2014-01-11 21:59:06.0', 'WebsiteUrl': 'http://jugsi.blogspot.it', 'Location': 'Italy', 'AboutMe': '<p><a href="http://www.linkedin.com/in/giacomoveneri" rel="nofollow">Giacomo Veneri</a> (Siena on 11/17/1973) graduated in Telecommunications Engineering in 1999. From 1999 to 2004 he collaborated with the University of Siena as an expert of Human Computer Interaction in the context of Multimedia and Bioengineering. From 2004 to 2006 he collaborated with major international financial institutions in the field of trading and in information visualization. On 2006 he was Technical Director and Director of the research laboratory (accredited MIUR) of <a href="http://albolaboratori.miur.it/Regione.aspx?LabCat=310" rel="nofollow">Etruria Innovation SPA</a>. From 2012 is PhD graduated at the Department of Neurological Sciences, University of Siena. <a href="http://scholar.google.it/citations?user=B40SHWAAAAAJ&amp;hl=it" rel="nofollow">It deals with human computer interaction and human mechanisms that underlie human-machine interaction</a>. He is <a href="http://2.bp.blogspot.com/-PU9WZ2NvpCY/Uj6ae8NbHVI/AAAAAAAABfo/SeCAuXjVKtU/s1600/gvaneri_certificate.png" rel="nofollow">Java 7 OCA Associated certified</a>.</p>\n', 'Views': 3, 'UpVotes': 0, 'DownVotes': 0, 'AccountId': 1808870, 'Age': 41, 'ProfileImageUrl': 'https://www.gravatar.com/avatar/eecdecec53a6c9fddbcad6bf1dd99c21?s=128&d=identicon&r=PG'}
