User: {'Id': 37293, 'Reputation': 101, 'CreationDate': '2014-01-14 03:43:56.0', 'DisplayName': 'Austin Mohr', 'LastAccessDate': '2014-01-14 03:43:56.0', 'WebsiteUrl': 'http://www.austinmohr.com', 'Location': 'Lincoln, NE', 'AboutMe': '<p><b>Status</b><br />\nAssistant Professor in the <a href="http://www.nebrwesleyan.edu/academics/academic-departments/mathematics-and-computer-science-department" rel="nofollow">Department of Mathematics</a> at <a href="http://www.nebrwesleyan.edu/" rel="nofollow">Nebraska Wesleyan University</a></p>\n\n<p><b>Interests</b><br />\nCombinatorics, general topology, and mathematics pedagogy</p>\n\n<p><b>Currently Researching</b><br />\n<a href="http://www.austinmohr.com/Work_files/questpub.pdf" rel="nofollow">Applications of the Lopsided Lovász Local Lemma</a></p>\n\n<p><b>Spacebook</b><br />\n<a href="http://www.austinmohr.com/spacebook" rel="nofollow">Spacebook</a> is a searchable database of <a href="http://en.wikipedia.org/wiki/Topological_space" rel="nofollow">topological spaces</a> and their properties (in <a href="http://en.wikipedia.org/wiki/Zermelo%E2%80%93Fraenkel_set_theory" rel="nofollow">ZFC</a>) inspired by Steen and Seebach&#8217;s <em><a href="http://books.google.com/books/about/Counterexamples_in_Topology.html?id=DkEuGkOtSrUC" rel="nofollow" title="Counterexamples in Topology">Counterexamples in Topology</a></em>. (<a href="http://austinmohr.com/?page_id=291" rel="nofollow" title="About Spacebook">Learn more</a>.)</p></p>\n', 'Views': 0, 'UpVotes': 3, 'DownVotes': 0, 'AccountId': 511882, 'Age': 29, 'ProfileImageUrl': 'http://i.stack.imgur.com/G3sqY.jpg'}
User: {'Id': 37294, 'Reputation': 21, 'CreationDate': '2014-01-14 05:11:57.0', 'DisplayName': '9codeMan9', 'LastAccessDate': '2014-09-10 08:26:34.0', 'WebsiteUrl': None, 'Location': None, 'AboutMe': '<p>I am a graduate student in IST with a background in Computer Science and Engineering, Philosophy, and Mathematics.  I am currently conducting research in Creative Systems and applied Artificial Intelligence &amp; Machine Learning.</p>\n\n<p>My interests include:</p>\n\n<ul>\n<li>Artificial Intelligence:  Intelligent Agents, Neural Networks, and Knowledge\nRepresentation </li>\n<li>Complex Systems, Artificial Intuition &amp; Artificial Creativity</li>\n<li>Machine Learning/Datamining</li>\n<li>Robotics (from an AI-agents perspective)</li>\n<li>Computer Graphics and Computer Vision</li>\n<li>How human agents and software agents can work together to solve problems (HCI + AI)</li>\n<li>Lambda Calculus, Interpreters</li>\n</ul>\n', 'Views': 2, 'UpVotes': 0, 'DownVotes': 0, 'AccountId': 2057766, 'Age': None, 'ProfileImageUrl': 'http://i.stack.imgur.com/8KhXI.jpg?s=128&g=1'}
